/* Avatar interactivo de Fer (WebGL). Markup: #av > #jelly > canvas#c + #bubble */
(() => {
const SRC = "data:image/jpeg;base64,";
const S = 273;               // todas las coordenadas de la cara están en px de la foto original
const SLEEP_AFTER = 8000;    // ms sin actividad hasta dormirse
const F = { eyeL:[127,106.3], eyeR:[185.8,92.8], nose:[161,127], mouth:[168,157], browL:[126,87], browR:[181,75], face:[160,122], cheekL:[119,139], cheekR:[204,124] };

const $ = id => document.getElementById(id);
const canvas=$('c'), jelly=$('jelly'), bubble=$('bubble');
const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();

// ---------- WebGL ----------
const gl = canvas.getContext('webgl', { premultipliedAlpha:false, antialias:false });
if (!gl) { canvas.replaceWith(Object.assign(new Image(), { src:SRC, style:'width:100%;border-radius:50%;position:relative' })); }
const VS = `attribute vec2 a; varying vec2 v; void main(){ v = vec2(a.x*.5+.5, .5-a.y*.5); gl_Position = vec4(a,0.,1.); }`;
const FS = `
precision highp float;
varying vec2 v; uniform sampler2D t0;
uniform vec2 eyeL, eyeR, nose, mouth, browL, browR, face, cheekL, cheekR;
uniform vec2 lookL, lookR;
uniform float winkL, winkR;
uniform float gNose, gEyes, gMouth, gSwirl, gBrow, gCheek, gBig;
uniform vec2 grab, pull;
const vec2 AX = vec2(0.975,-0.223);
const vec2 AY = vec2(0.223, 0.975);
float fall(float r){ float k = clamp(1.-r*r,0.,1.); return k*k; }
vec2 bulge(vec2 p, vec2 c, float R, float s){ vec2 d=p-c; return c + d*(1.-s*fall(length(d)/R)); }
vec2 bulgeE(vec2 p, vec2 c, vec2 R, float s){ vec2 d=p-c; return c + d*(1.-s*fall(length(d/R))); }
vec2 look(vec2 p, vec2 c, vec2 d){
  vec2 q=p-c; float e=length(vec2(dot(q,AX)/10.5, dot(q,AY)/6.2));
  return p - d*smoothstep(1.,.42,e);
}
vec2 wink(vec2 p, vec2 c, float w, out float lash){
  lash = 0.;
  if (w < .001) return p;
  vec2 q=p-c; float u=dot(q,AX), y=dot(q,AY)-2.6; const float R=11.;
  float hx = smoothstep(1.,.45,abs(u)/16.);
  float ay = abs(y);
  if (ay < R) {
    float a = mix(1., .2, w*hx);
    float ys = sign(y)*R*pow(ay/R, a);
    p += AY*(ys-y);
    float curve = y - .9 + u*u*.012;
    lash = w*w*smoothstep(1.3,.2,abs(curve))*smoothstep(11.,8.,abs(u));
  }
  return p;
}
void main(){
  vec2 p = v*${S}.;
  float pl = length(pull);
  if (pl > .01) p -= pull*fall(length(p-(grab+pull))/78.);
  p = bulge(p, face, 150., .42*gBig);
  if (abs(gSwirl) > .001) { vec2 d=p-face; float a=gSwirl*2.4*fall(length(d)/95.); float s=sin(a), c=cos(a); p = face + vec2(c*d.x-s*d.y, s*d.x+c*d.y); }
  p = bulge(p, cheekL, 40., .55*gCheek);
  p = bulge(p, cheekR, 40., .55*gCheek);
  p = bulgeE(p, mouth, vec2(40.,24.), -.75*gCheek);
  p = bulge(p, nose, 46., .62*gNose);
  p = bulgeE(p, mouth, vec2(52.,30.), .5*gMouth);
  p = bulge(p, eyeL, 21., .52*gEyes);
  p = bulge(p, eyeR, 21., .52*gEyes);
  p.y += gBrow*7.*(fall(length((p-browL)/vec2(26.,13.))) + fall(length((p-browR)/vec2(26.,13.))));
  float l1, l2;
  p = wink(p, eyeL, winkL, l1);
  p = wink(p, eyeR, winkR, l2);
  p = look(p, eyeL, lookL*(1.-winkL));
  p = look(p, eyeR, lookR*(1.-winkR));
  vec2 uv = clamp(p/${S}., 0., 1.);
  vec3 col = texture2D(t0, uv).rgb;
  col = mix(col, vec3(.13,.09,.08), .8*max(l1,l2));
  gl_FragColor = vec4(col,1.);
}`;
let ready=0; const UL={}; const U = n => UL[n] || (UL[n]=gl.getUniformLocation(prog,n)); let prog;
if (gl) {
  const sh=(type,src)=>{ const s=gl.createShader(type); gl.shaderSource(s,src); gl.compileShader(s); if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)) console.error(gl.getShaderInfoLog(s)); return s; };
  prog = gl.createProgram(); gl.attachShader(prog, sh(gl.VERTEX_SHADER,VS)); gl.attachShader(prog, sh(gl.FRAGMENT_SHADER,FS)); gl.linkProgram(prog); gl.useProgram(prog);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1,1,-1,-1,1,1,1]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog,'a'); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  for (const k in F) gl.uniform2f(U(k), F[k][0], F[k][1]);
  gl.uniform1i(U('t0'),0);
  const load=(unit,src)=>{ const img=new Image(); img.onload=()=>{
      const source=img;
      gl.activeTexture(gl.TEXTURE0+unit); gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
      try { gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,source); } catch(e){ console.error(e); }
      for (const [k,val] of [[gl.TEXTURE_MIN_FILTER,gl.LINEAR],[gl.TEXTURE_MAG_FILTER,gl.LINEAR],[gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE],[gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D,k,val);
      ready = 1;
    }; img.src=src; };
  load(0,SRC);
}
function resize(){ const d=Math.min(devicePixelRatio||1,2), w=Math.round(canvas.clientWidth*d); if(canvas.width!==w){ canvas.width=canvas.height=w; gl.viewport(0,0,w,w);} }

// ---------- estado ----------
const spring = (v=0) => ({ x:v, v:0, to:v });
const step = (s, k, c, dt) => { s.v += (k*(s.to-s.x) - c*s.v)*dt; s.x += s.v*dt; };
const clamp = (x,a,b) => Math.max(a,Math.min(b,x));
const st = {
  mouse:null, lastMove:0, lastActive:performance.now(), asleep:false,
  look:{ x:0, y:0 }, tilt:null,
  wink:{ L:spring(), R:spring() }, nextWink:'R', lastWink:0,
  g:{ nose:spring(), eyes:spring(), mouth:spring(), swirl:spring(), brow:spring() }, cross:spring(),
  cheek:spring(), big:spring(),
  scrollLook:spring(), lastScrollY:scrollY, lastScrollT:0,
  dizzyUntil:0, shake:[], lastDX:0,
  pull:{ x:spring(), y:spring() }, grab:[S/2,S/2],
  sx:spring(1), sy:spring(1), rot:spring(0),
  drag:null, pointers:new Map(), pinch:null, puffed:false, longT:0, lastClick:0,
  gi:0, nextBlink:performance.now()+2500, typeT:0, typing:false
};
const hint = () => {};
let bubbleT;
function say(txt, ms=1100){ bubble.textContent=txt; bubble.classList.add('on'); clearTimeout(bubbleT); if(ms) bubbleT=setTimeout(()=>bubble.classList.remove('on'),ms); }

// ---------- actividad / dormirse ----------
function active(){
  st.lastActive=performance.now();
  if (st.asleep) { st.asleep=false; st.wink.L.to=0; st.wink.R.to=0; st.rot.to=0; st.g.brow.to=1.2; setTimeout(()=>{ if(!gestureActive(true)) st.g.brow.to=0; },500); st.sy.v+=3; say('¡Ah! Acá estoy'); hint('sleep'); }
}
function sleep(){ st.asleep=true; resetGesture(); st.wink.L.to=1; st.wink.R.to=1; say('Zzz…',0); }

// ---------- gestos al hacer clic ----------
const GESTURES = [
  { name:'¡Narizota!',  on(){ st.g.nose.to=1; st.cross.to=1; } },
  { name:'¡Ojazos!',    on(){ st.g.eyes.to=1; st.g.brow.to=1; } },
  { name:'¡Sonrisota!', on(){ st.g.mouth.to=1; st.g.brow.to=.6; } },
];
let gestureT;
function gesture(){
  resetGesture(); GESTURES[st.gi++ % GESTURES.length].on(); bubble.classList.remove('on');
  st.sx.v += 2.2; st.sy.v -= 2.2;
  clearTimeout(gestureT); gestureT = setTimeout(resetGesture, 900);
  hint('click');
}
function resetGesture(){ clearTimeout(gestureT); for (const k in st.g) st.g[k].to=0; st.cross.to=0; if(!st.asleep){ st.wink.L.to=0; st.wink.R.to=0; } }
const gestureActive = (ignoreBrow) => Object.entries(st.g).some(([k,s])=>s.to!==0 && !(ignoreBrow&&k==='brow'));

// ---------- easter eggs ----------
function spin(){ resetGesture(); st.rot.x -= 360; st.rot.v = 0; st.sx.v+=3; st.sy.v+=3; say('¡Wiii!'); winkNow('R',true); hint('dbl'); }
function dizzy(){ st.dizzyUntil=performance.now()+1900; st.cross.to=1; say('¡Me mareé! 😵‍💫',1900); hint('shake'); }
function confetti(){
  const r=canvas.getBoundingClientRect(), cx=r.left+r.width/2, cy=r.top+r.height/2, cols=[css('--accent'),css('--green'),css('--ink'),'#c9605a'];
  for (let i=0;i<46;i++){ const el=document.createElement('i'); el.className='confetti'; el.style.background=cols[i%4]; el.style.left=cx+'px'; el.style.top=cy+'px'; document.body.appendChild(el);
    const a=Math.random()*Math.PI*2, d=120+Math.random()*260, x=Math.cos(a)*d, y=Math.sin(a)*d-120;
    el.animate([{transform:'translate(-50%,-50%) rotate(0)',opacity:1},{transform:`translate(${x}px,${y}px) rotate(${Math.random()*720-360}deg)`,opacity:1,offset:.7},{transform:`translate(${x*1.1}px,${y+220}px) rotate(${Math.random()*900}deg)`,opacity:0}],{duration:1300+Math.random()*600,easing:'cubic-bezier(.2,.7,.3,1)'}).onfinish=()=>el.remove(); }
}
const KONAMI='ArrowUp,ArrowUp,ArrowDown,ArrowDown,ArrowLeft,ArrowRight,ArrowLeft,ArrowRight,b,a';
let konami=[];
addEventListener('keydown', e => {
  active();
  konami.push(e.key.length===1?e.key.toLowerCase():e.key); konami=konami.slice(-10);
  if (konami.join(',')===KONAMI) { clearTimeout(st.typeT); st.typing=false; st.cheek.to=0; st.g.brow.to=0; st.big.to=1; say('¡Cabezona!',1600); confetti(); setTimeout(()=>st.big.to=0,1600); return; }
  // tipear infla los cachetes; al dejar de escribir, desinfla (no reacciona si se escribe en un campo de formulario)
  if (e.target.closest && e.target.closest('input,textarea,select,[contenteditable]')) return;
  if (e.key.length===1 && !e.ctrlKey && !e.metaKey && !e.altKey && !st.drag) {
    if (!st.typing) { st.typing=true; resetGesture(); st.cheek.to=1; st.g.brow.to=.8; say('Mmmf…',0); }
    clearTimeout(st.typeT); st.typeT=setTimeout(()=>{ st.typing=false; if (st.puffed) return; st.cheek.to=0; st.g.brow.to=0; st.sx.v+=3; st.sy.v-=3; say('¡Pfff!'); }, 450);
  }
});

// ---------- guiño / parpadeo ----------
function winkNow(side, force){
  const now=performance.now(); if (!force && now-st.lastWink<650) return; st.lastWink=now;
  side = side || st.nextWink; st.nextWink = side==='R'?'L':'R';
  st.wink[side].to=1; setTimeout(()=>{ if(!st.asleep) st.wink[side].to=0; }, 280);
  st.rot.v += (side==='R'?1:-1)*38;
}
function blink(){ st.wink.L.to=1; st.wink.R.to=1; setTimeout(()=>{ if(!gestureActive()&&!st.asleep){ st.wink.L.to=0; st.wink.R.to=0; } },110); }

// ---------- scroll: mira hacia donde vas ----------
function scrolled(d){ if (Math.abs(d)<1) return; active(); st.scrollLook.to=Math.sign(d); st.lastScrollT=performance.now(); }
addEventListener('wheel', e => scrolled(e.deltaY), { passive:true });
addEventListener('scroll', () => { const y=scrollY; scrolled(y-st.lastScrollY); st.lastScrollY=y; }, { passive:true });

// ---------- mouse / touch ----------
addEventListener('pointermove', e => {
  active();
  if (e.pointerType==='mouse') {
    // sacudida: muchos cambios de dirección rápidos = mareo
    const now=performance.now(), dx=e.movementX||0;
    if (Math.abs(dx)>14 && Math.sign(dx)!==Math.sign(st.lastDX) && st.lastDX!==0) { st.shake.push(now); st.shake=st.shake.filter(t=>now-t<900); if (st.shake.length>=6 && now>st.dizzyUntil+800 && !st.drag) { st.shake=[]; dizzy(); } }
    if (Math.abs(dx)>14) st.lastDX=dx;
    if (!st.drag) hint('look');
  }
  st.mouse=[e.clientX,e.clientY]; st.lastMove=performance.now();
  if (st.pointers.has(e.pointerId)) st.pointers.set(e.pointerId,[e.clientX,e.clientY]);
  if (st.pinch && st.pointers.size>=2) {            // pellizco con dos dedos
    const [a,b]=[...st.pointers.values()], d=Math.hypot(a[0]-b[0],a[1]-b[1]), s=clamp(d/st.pinch,.45,1.9);
    st.sx.to=s; st.sy.to=s; return;
  }
  if (!st.drag) return;
  const d=st.drag, r=d.rect, k=S/r.width;
  let dx=(e.clientX-d.x)*k, dy=(e.clientY-d.y)*k;
  if (Math.hypot(e.clientX-d.x,e.clientY-d.y)>6 && !st.puffed) { d.moved=true; clearTimeout(st.longT); hint('drag'); }
  if (!d.moved) return;
  const m=Math.hypot(dx,dy), lim=58, f=m>lim? lim*(1+Math.log(m/lim)*.25)/m : 1;
  st.pull.x.to=dx*f; st.pull.y.to=dy*f;
  const nx=d.n[0], ny=d.n[1];
  let ex=clamp((dx*Math.sign(nx||1))/S*1.1*Math.min(1,Math.abs(nx)*2.5+.25),-.42,.55);
  let ey=clamp((dy*Math.sign(ny||1))/S*1.1*Math.min(1,Math.abs(ny)*2.5+.25),-.42,.55);
  st.sx.to=(1+ex)/Math.sqrt(1+ey); st.sy.to=(1+ey)/Math.sqrt(1+ex);
});
canvas.addEventListener('pointerdown', e => {
  active(); askTilt();
  const r=canvas.getBoundingClientRect(); try { canvas.setPointerCapture(e.pointerId); } catch(_){}
  st.pointers.set(e.pointerId,[e.clientX,e.clientY]);
  if (st.pointers.size===2) {
    const [a,b]=[...st.pointers.values()]; st.pinch=Math.hypot(a[0]-b[0],a[1]-b[1])||1;
    clearTimeout(st.longT); if (st.drag) st.drag.moved=true; st.pull.x.to=0; st.pull.y.to=0; return;
  }
  const gx=(e.clientX-r.left)/r.width, gy=(e.clientY-r.top)/r.height;
  st.grab=[gx*S,gy*S];
  st.drag={ x:e.clientX, y:e.clientY, rect:r, moved:false, n:[gx-.5,gy-.5] };
  canvas.classList.add('grabbing');
  // clic largo: infla los cachetes
  clearTimeout(st.longT); st.longT=setTimeout(()=>{ if (st.drag && !st.drag.moved) { st.puffed=true; resetGesture(); st.cheek.to=1; st.g.brow.to=.8; say('Mmmf…',0); hint('long'); } }, 420);
});
canvas.addEventListener('contextmenu', e => e.preventDefault());
function release(e){
  st.pointers.delete(e.pointerId); clearTimeout(st.longT);
  if (st.pinch) { if (st.pointers.size<2) { st.pinch=null; st.sx.to=1; st.sy.to=1; } if (st.pointers.size) return; st.drag=null; canvas.classList.remove('grabbing'); return; }
  if (!st.drag) return; const moved=st.drag.moved; st.drag=null; canvas.classList.remove('grabbing');
  st.pull.x.to=0; st.pull.y.to=0; st.sx.to=1; st.sy.to=1;
  if (st.puffed) { st.puffed=false; if (st.typing) return; st.cheek.to=0; st.g.brow.to=0; st.sx.v+=3; st.sy.v-=3; say('¡Pfff!'); return; }
  if (moved) return;
  const now=performance.now();
  if (now-st.lastClick<320) { st.lastClick=0; spin(); } else { st.lastClick=now; gesture(); }
}
addEventListener('pointerup', release); addEventListener('pointercancel', release);

// ---------- celular: los ojos siguen la inclinación del teléfono ----------
let tiltAsked=false;
function onTilt(e){ if (e.gamma==null) return; st.tilt=[clamp(e.gamma/30,-1,1), clamp((e.beta-45)/30,-1,1)]; }
function askTilt(){
  if (tiltAsked || !window.DeviceOrientationEvent) return; tiltAsked=true;
  try {
    if (typeof DeviceOrientationEvent.requestPermission==='function') DeviceOrientationEvent.requestPermission().then(s=>{ if(s==='granted') addEventListener('deviceorientation',onTilt); }).catch(()=>{});
  } catch(_){}
}
try { if (window.DeviceOrientationEvent && typeof DeviceOrientationEvent.requestPermission!=='function') addEventListener('deviceorientation',onTilt); } catch(_){}

// ---------- loop ----------
let last=performance.now();
function frame(now){
  requestAnimationFrame(frame);
  const dt=Math.min(.033,(now-last)/1000); last=now;
  if (!gl || !ready) return; resize();
  const r=canvas.getBoundingClientRect();

  if (!st.asleep && now-st.lastActive>SLEEP_AFTER && !st.drag) sleep();
  if (now-st.lastScrollT>350) st.scrollLook.to=0;

  // hacia dónde mira: elemento con hover > cursor > inclinación del teléfono > paseo
  let tx, ty; const cx=r.left+r.width*(F.face[0]/S), cy=r.top+r.height*(100/S);
  const aim=(px,py)=>{ const dx=px-cx, dy=py-cy, m=Math.hypot(dx,dy)||1, a=Math.min(1,m/Math.max(120,r.width*.9)); tx=dx/m*a; ty=dy/m*a; };
  if (st.mouse && now-st.lastMove<4000) aim(st.mouse[0],st.mouse[1]);
  else if (st.tilt) { tx=st.tilt[0]; ty=st.tilt[1]; }
  else { tx=Math.sin(now/1300)*.55; ty=Math.sin(now/1900+1)*.3; }
  step(st.scrollLook,120,16,dt);
  const sl=st.scrollLook.x; ty=clamp(ty*(1-Math.abs(sl))+sl*1.5,-1.5,1.5); tx*=1-Math.abs(sl)*.6;
  const e=1-Math.exp(-dt*14); st.look.x+=(tx-st.look.x)*e; st.look.y+=(ty-st.look.y)*e;

  // mareo
  const dizzyOn = now<st.dizzyUntil;
  if (dizzyOn) { const k=(st.dizzyUntil-now)/1900; st.g.swirl.to=Math.sin(now/95)*.75*k; st.rot.to=Math.sin(now/140)*9*k; }
  else if (st.dizzyUntil) { st.dizzyUntil=0; st.g.swirl.to=0; st.cross.to=0; st.rot.to=0; }
  // dormida: cabecea
  if (st.asleep) { const t=(now-st.lastActive-SLEEP_AFTER)/1000; st.rot.to=7+Math.sin(t*1.6)*5; st.sy.to=1+Math.sin(t*1.6)*.025; }
  else if (!st.drag && !st.pinch && !dizzyOn) { st.rot.to = 0; }

  for (const k in st.g) step(st.g[k],260,17,dt);
  step(st.cross,260,20,dt); step(st.cheek,90,9,dt); step(st.big,200,14,dt);
  const wk=st.asleep?60:900, wc=st.asleep?14:46;
  step(st.wink.L,wk,wc,dt); step(st.wink.R,wk,wc,dt);
  const held=st.drag||st.pinch;
  step(st.pull.x, held?700:230, held?48:9, dt); step(st.pull.y, held?700:230, held?48:9, dt);
  step(st.sx, held?500:210, held?40:8, dt); step(st.sy, held?500:210, held?40:8, dt);
  step(st.rot, st.asleep?20:180, st.asleep?7:9, dt);
  if (now>st.nextBlink) { st.nextBlink=now+2200+Math.random()*3800; if(!gestureActive()&&!st.asleep&&!st.puffed&&!st.typing&&now-st.lastWink>900) blink(); }

  const c=clamp(st.cross.x,0,1), LX=3.3, LY=1.9;
  const lL=[st.look.x*LX*(1-c)+3.2*c, st.look.y*LY*(1-c)+1.2*c];
  const lR=[st.look.x*LX*(1-c)-3.2*c, st.look.y*LY*(1-c)+1.2*c];
  // al mirar abajo bajan un poco los párpados; al mirar arriba suben las cejas
  const lid=clamp(sl,0,1)*.32, up=clamp(-sl,0,1)*.6;
  gl.uniform2f(U('lookL'),lL[0],lL[1]); gl.uniform2f(U('lookR'),lR[0],lR[1]);
  gl.uniform1f(U('winkL'),clamp(st.wink.L.x+lid,0,1)); gl.uniform1f(U('winkR'),clamp(st.wink.R.x+lid,0,1));
  gl.uniform1f(U('gNose'),st.g.nose.x); gl.uniform1f(U('gEyes'),st.g.eyes.x); gl.uniform1f(U('gMouth'),st.g.mouth.x);
  gl.uniform1f(U('gSwirl'),st.g.swirl.x); gl.uniform1f(U('gBrow'),st.g.brow.x+up);
  gl.uniform1f(U('gCheek'),st.cheek.x); gl.uniform1f(U('gBig'),st.big.x);
  gl.uniform2f(U('grab'),st.grab[0],st.grab[1]); gl.uniform2f(U('pull'),st.pull.x.x,st.pull.y.x);
  gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
  jelly.style.transform=`rotate(${st.rot.x.toFixed(2)}deg) scale(${st.sx.x.toFixed(4)},${st.sy.x.toFixed(4)})`;
}
requestAnimationFrame(frame);
window.__avatar = { st, gesture, winkNow, dizzy, spin, confetti, sleep };
})();
